  "path": "supabase/functions/user-stats/index.ts",
  "contents": "import "@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "npm:@supabase/supabase-js@2";

const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
const anonKey = Deno.env.get("SUPABASE_ANON_KEY") ?? "";
const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";

const jsonHeaders = {
  "Content-Type": "application/json",
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), { status, headers: jsonHeaders });
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: jsonHeaders });
  if (req.method !== "POST") return json({ error: "method not allowed" }, 405);

  // The service-role key is accepted only in apikey. It is never accepted as
  // a user bearer token, and is never sent to a client-facing Supabase client.
  const apiKey = req.headers.get("apikey");
  const isInternalService = Boolean(serviceRoleKey) && apiKey === serviceRoleKey;

  let body: { user_id?: unknown };
  try {
    body = await req.json();
  } catch {
    return json({ error: "request body must be valid JSON" }, 400);
  }

  if (isInternalService) {
    const userId = body.user_id;
    if (typeof userId !== "string" ||
        !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(userId)) {
      return json({ error: "user_id must be a valid UUID" }, 400);
    }

    const admin = createClient(supabaseUrl, serviceRoleKey, {
      auth: { autoRefreshToken: false, persistSession: false },
    });
    const { data, error } = await admin
      .from("user_stats")
      .select("*")
      .eq("user_id", userId);

    if (error) {
      console.error("service stats query failed", error);
      return json({ error: "could not load stats" }, 500);
    }
    return json(data ?? []);
  }

  // A non-service caller must present a real Auth access token. Ignore any
  // user_id in its body: the identity in the verified token is authoritative.
  const authorization = req.headers.get("Authorization") ?? "";
  if (!/^Bearer\s+\S+$/i.test(authorization)) {
    return json({ error: "unauthorized" }, 401);
  }
  const accessToken = authorization.replace(/^Bearer\s+/i, "");
  if (!supabaseUrl || !anonKey) return json({ error: "server configuration error" }, 500);

  const userClient = createClient(supabaseUrl, anonKey, {
    auth: { autoRefreshToken: false, persistSession: false },
    global: { headers: { Authorization: `Bearer ${accessToken}` } },
  });
  const { data: userData, error: userError } = await userClient.auth.getUser(accessToken);
  if (userError || !userData.user) return json({ error: "unauthorized" }, 401);

  // This query is also protected by the table's authenticated RLS policy.
  const { data, error } = await userClient
    .from("user_stats")
    .select("*")
    .eq("user_id", userData.user.id);
  if (error) {
    console.error("user stats query failed", error);
    return json({ error: "could not load stats" }, 500);
  }
  return json(data ?? []);
});
"
}

